@Component("insuredObject-subscriber")
public class InsuredObjectSubscriber extends BaseSubscriber {

	public InsuredObjectSubscriber() {
	}
	
    public SubscriptionQueryResult<List<InsuredObject>, InsuredObject> insuredObjectSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllInsuredObjectQuery(), 
                		ResponseTypes.multipleInstancesOf(InsuredObject.class),
                		ResponseTypes.instanceOf(InsuredObject.class));
    }

    public SubscriptionQueryResult<InsuredObject, InsuredObject> insuredObjectSubscribe(@DestinationVariable UUID insuredObjectId) {
        return queryGateway
                .subscriptionQuery(new FindInsuredObjectQuery(new LoadInsuredObjectFilter(insuredObjectId)), 
                		ResponseTypes.instanceOf(InsuredObject.class),
                		ResponseTypes.instanceOf(InsuredObject.class));
    }





}

